select id, status, round(amount / sum(amount) over (partition by year(paid_at), order_id), 4) as amount_share, row_number() over w_part as event_seq, row_number() over w_part as seq_no, row_number() over (partition by method order by amount, id) as row_seq, row_number() over w_recent as row_seq_2 from payments window w_part as (partition by method order by paid_at, id), w_recent as (partition by status, order_id order by amount, id);
